return (async () => {
  for (const d of document.querySelectorAll("acme-drawer[id]")) { d.show(); await d.updateComplete; await d.updateComplete; }
  const panel = (id) => document.querySelector("acme-drawer#" + id).shadowRoot.querySelector(".drawer");
  panel("open-scrolled").scrollTop = 160;
  const p = panel("open-dragging");
  const ev = (type, y) => new PointerEvent(type, { clientY: y, pointerId: 1, pointerType: "mouse", button: 0, bubbles: true, composed: true });
  p.dispatchEvent(ev("pointerdown", 100));
  p.dispatchEvent(ev("pointermove", 180));
  await document.querySelector("acme-drawer#open-dragging").updateComplete;
})();
